select (addressNullCount*100)/total_count as percent_address_null
from (
select count(*) as total_count,
(select count(*) from <[Acquia].[pdp_acquia_contact_export]> as ce where address_line_1 is null) as addressNullCount
from <[Acquia].[pdp_acquia_contact_export]> as ce
) Measure

(select a.total_null as Max_Null_Percent from
(select max(percent_null) total_null from
(
select (addressNullCount*100)/total_count as percent_null
from (
select count(*) as total_count,
(select count(*) from <[Acquia].[pdp_acquia_contact_export]> as ce where address_line_1 is null) as addressNullCount
from <[Acquia].[pdp_acquia_contact_export]> as ce
) Measure

union all
select (birthdateNullCount*100)/total_count as percent_null
from (
select count(*) as total_count,
(select count(*) from <[Acquia].[pdp_acquia_contact_export]> as ce where student_date_of_birth is null) as birthdatenullcount
from <[Acquia].[pdp_acquia_contact_export]> as ce
) Measure

union all
select (FunnelStatusNullCount*100)/total_count as percent_null
from (
select count(*) as total_count,
(select count(*) from <[Acquia].[pdp_acquia_contact_export]> as ce where funnel_stage_calculated is null) as funnelstatusnullcount
from <[Acquia].[pdp_acquia_contact_export]> as ce
) Measure
)b
)a)

(select (birthdateNullCount*100)/total_count as stu_birthdate_null_percentage
from (
select count(*) as total_count,
(select count(*) from <[Acquia].[pdp_acquia_contact_export]> as ce where student_date_of_birth is null) as birthdatenullcount
from <[Acquia].[pdp_acquia_contact_export]> as ce
) Measure)

select (gradeLevelNullCount*100)/total_count as gradelevel_percent_null
from (
select count(*) as total_count,
(select count(*) from <[Acquia].[pdp_acquia_contact_export]> as ce where student_high_school_grade_level_calculated is null) as gradeLevelNullCount
from <[Acquia].[pdp_acquia_contact_export]> as ce
) Measure

-- 05/16/2022 Add lower(eab_phone_type) at case statements
select	e.primary_student_id,
		listagg(e.home_phone) home_phone,
		listagg(e.cell_phone) cell_phone
from(	select	d.primary_student_id,
				case when d.Phone_type = 'home' then d.phone_number else '' end  home_phone,
				case when d.Phone_type = 'cell' then d.phone_number else '' end  cell_phone
		from(	select c.*
				from(	select 	b.primary_student_id,
								b.eab_phone_type,
								b.phone_number,
								row_number() over (partition by b.primary_student_id, b.Phone_type order by b.phone_number desc) priority_rank,
								b.Phone_type
						from (	select 	a.primary_student_id, a.phone_number, a.eab_phone_type,
								case when lower(a.eab_phone_type) = 'home' then 'home' else 'cell' end as Phone_type
								from <[ALR].[Student Phone].{final}> a
							)b
					)c
				where c.priority_rank = 1
			)d
	)e
group by e.primary_student_id
order by e.primary_student_id

select   primary_student_id ,  listagg(previous_college_name_1)   as   previous_college_name_1 ,  listagg(previous_college_name_2)   as   previous_college_name_2 ,  listagg(previous_college_name_3)   as   previous_college_name_3 ,  listagg(previous_college_ceeb_cd_1)   as   previous_college_ceeb_cd_1 ,  listagg(previous_college_ceeb_cd_2)   as   previous_college_ceeb_cd_2 ,  listagg(previous_college_ceeb_cd_3)   as   previous_college_ceeb_cd_3 ,  listagg(previous_college_gpa_1)   as   previous_college_gpa_1 ,  listagg(previous_college_gpa_2)   as   previous_college_gpa_2 ,  listagg(previous_college_gpa_3)   as   previous_college_gpa_3 ,  listagg(previous_college_major)   as   previous_college_major

from   (
select   primary_student_id ,  (case when priority_rank = 1 then college_name else '' end)   as   previous_college_name_1 ,  (case when priority_rank = 2 then college_name else '' end)   as   previous_college_name_2 ,  (case when priority_rank = 3 then college_name else '' end)   as   previous_college_name_3 ,  (case when priority_rank = 1 then college_ceeb_cd else '' end)   as   previous_college_ceeb_cd_1 ,  (case when priority_rank = 2 then college_ceeb_cd else '' end)   as   previous_college_ceeb_cd_2 ,  (case when priority_rank = 3 then college_ceeb_cd else '' end)   as   previous_college_ceeb_cd_3 ,  (case when priority_rank = 1 then college_gpa_nbr else '' end)   as   previous_college_gpa_1 ,  (case when priority_rank = 2 then college_gpa_nbr else '' end)   as   previous_college_gpa_2 ,  (case when priority_rank = 3 then college_gpa_nbr else '' end)   as   previous_college_gpa_3 ,  (case when priority_rank = 1 then college_major else '' end)   as   previous_college_major
from   (
select   student_prior_college.primary_student_id   as   primary_student_id ,  (case 
when len(student_prior_college.college_name)<=100 then student_prior_college.college_name 
else substring(student_prior_college.college_name,1,100)   
end) as   college_name ,  (case when len(student_prior_college.college_ceeb_cd)<=6 then student_prior_college.college_ceeb_cd else '' end)  as   college_ceeb_cd ,  (case when len(student_prior_college.undergraduate_institution_major)<=100 then student_prior_college.undergraduate_institution_major else substring(student_prior_college.undergraduate_institution_major,1,100) end)  as   college_major ,  (case when len(student_prior_college.college_gpa_nbr)<=5 then student_prior_college.college_gpa_nbr else substring(student_prior_college.college_gpa_nbr,1,5) end) as   college_gpa_nbr ,  row_number() over (partition by primary_student_id order by  observation_time   desc )   as   priority_rank
  --select *
from    <[ALR].[Student Prior College]>  as student_prior_college
) as A
where  priority_rank <= 3
) as cte_student_prior_college
group by   primary_student_id
order by   primary_student_id   ASC

select   primary_student_id ,  listagg(previous_college_name_1)   as   previous_college_name_1 ,  listagg(previous_college_name_2)   as   previous_college_name_2 ,  listagg(previous_college_name_3)   as   previous_college_name_3 ,  listagg(previous_college_ceeb_cd_1)   as   previous_college_ceeb_cd_1 ,  listagg(previous_college_ceeb_cd_2)   as   previous_college_ceeb_cd_2 ,  listagg(previous_college_ceeb_cd_3)   as   previous_college_ceeb_cd_3 ,  listagg(previous_college_gpa_1)   as   previous_college_gpa_1 ,  listagg(previous_college_gpa_2)   as   previous_college_gpa_2 ,  listagg(previous_college_gpa_3)   as   previous_college_gpa_3 ,  listagg(previous_college_major)   as   previous_college_major

from   (
select   primary_student_id ,  (case when priority_rank = 1 then college_name else '' end)   as   previous_college_name_1 ,  (case when priority_rank = 2 then college_name else '' end)   as   previous_college_name_2 ,  (case when priority_rank = 3 then college_name else '' end)   as   previous_college_name_3 ,  (case when priority_rank = 1 then college_ceeb_cd else '' end)   as   previous_college_ceeb_cd_1 ,  (case when priority_rank = 2 then college_ceeb_cd else '' end)   as   previous_college_ceeb_cd_2 ,  (case when priority_rank = 3 then college_ceeb_cd else '' end)   as   previous_college_ceeb_cd_3 ,  (case when priority_rank = 1 then college_gpa_nbr else '' end)   as   previous_college_gpa_1 ,  (case when priority_rank = 2 then college_gpa_nbr else '' end)   as   previous_college_gpa_2 ,  (case when priority_rank = 3 then college_gpa_nbr else '' end)   as   previous_college_gpa_3 ,  (case when priority_rank = 1 then college_major else '' end)   as   previous_college_major
from   (
select   student_prior_college.primary_student_id   as   primary_student_id ,  (case 
when len(student_prior_college.college_name)<=100 then student_prior_college.college_name 
else substring(student_prior_college.college_name,1,100)   
end) as   college_name ,  (case when len(student_prior_college.college_ceeb_cd)<=6 then student_prior_college.college_ceeb_cd else '' end)  as   college_ceeb_cd ,  (case when len(student_prior_college.undergraduate_institution_major)<=100 then student_prior_college.undergraduate_institution_major else substring(student_prior_college.undergraduate_institution_major,1,100) end)  as   college_major ,  (case when len(student_prior_college.college_gpa_nbr)<=5 then student_prior_college.college_gpa_nbr else substring(student_prior_college.college_gpa_nbr,1,5) end) as   college_gpa_nbr ,  row_number() over (partition by primary_student_id order by  observation_time   desc )   as   priority_rank
  --select *
from    <[ALR].[Student Prior College].{final}>  as student_prior_college
) as A
where  priority_rank <= 3
) as cte_student_prior_college
group by   primary_student_id
order by   primary_student_id   ASC

select   primary_student_id ,  listagg(previous_college_name_1)   as   previous_college_name_1 ,  listagg(previous_college_name_2)   as   previous_college_name_2 ,  listagg(previous_college_name_3)   as   previous_college_name_3 ,  listagg(previous_college_ceeb_cd_1)   as   previous_college_ceeb_cd_1 ,  listagg(previous_college_ceeb_cd_2)   as   previous_college_ceeb_cd_2 ,  listagg(previous_college_ceeb_cd_3)   as   previous_college_ceeb_cd_3 ,  listagg(previous_college_gpa_1)   as   previous_college_gpa_1 ,  listagg(previous_college_gpa_2)   as   previous_college_gpa_2 ,  listagg(previous_college_gpa_3)   as   previous_college_gpa_3 ,  listagg(previous_college_major)   as   previous_college_major

from   (
select   primary_student_id ,  (case when priority_rank = 1 then college_name else '' end)   as   previous_college_name_1 ,  (case when priority_rank = 2 then college_name else '' end)   as   previous_college_name_2 ,  (case when priority_rank = 3 then college_name else '' end)   as   previous_college_name_3 ,  (case when priority_rank = 1 then college_ceeb_cd else '' end)   as   previous_college_ceeb_cd_1 ,  (case when priority_rank = 2 then college_ceeb_cd else '' end)   as   previous_college_ceeb_cd_2 ,  (case when priority_rank = 3 then college_ceeb_cd else '' end)   as   previous_college_ceeb_cd_3 ,  (case when priority_rank = 1 then college_gpa_nbr else '' end)   as   previous_college_gpa_1 ,  (case when priority_rank = 2 then college_gpa_nbr else '' end)   as   previous_college_gpa_2 ,  (case when priority_rank = 3 then college_gpa_nbr else '' end)   as   previous_college_gpa_3 ,  (case when priority_rank = 1 then undergraduate_institution_major else '' end)   as   previous_college_major
from   (
select   student_prior_college.primary_student_id ,  substring(student_prior_college.college_name,1,50) as college_name ,  student_prior_college.college_ceeb_cd,  substring(student_prior_college.undergraduate_institution_major,1,50) as undergraduate_institution_major ,  student_prior_college.college_gpa_nbr,  row_number() over (partition by primary_student_id order by  observation_time   desc )   as   priority_rank
from    <[ALR].[Student Prior College].{final}>  as student_prior_college
) as A
where  priority_rank <= 3
) as cte_student_prior_college
group by   primary_student_id
order by   primary_student_id   ASC

(select distinct ((
   select count(a.<cond_item>) as record_total 
		from <CategoryOne> as a where <cond>
	   ) /
		(
		  select count(b.<cond_item>) as total 
			from <CategoryOne> as b
		)) as num
from <CategoryOne> as c)

(select  distinct ((
   select count(a.<cond_item>) as record_total 
		from <CategoryOne> as a where <cond>
	   ) /
		(
		  select count(b.<cond_item>) as total 
			from <CategoryOne> as b where <condtwo>
		)) as num
from <CategoryOne> as c)

(select  distinct ((
   select count(*) as record_total 
		from <CategoryOne> as a where <cond>
	   ) /
		(
		  select count(*) as total 
			from <CategoryOne> as b
		)) as num
from <CategoryOne> as c)

(
select  distinct ((
   select ifnull(sum(pp.record_count),0) as unknown_total 
		from <Base Tbl> as pp where field_name = 'address_type' and pp.eab_standard_value in ('Unmapped Value')
	   ) /
		(
		  select sum(pq.record_count)+1 as total 
			from <Base Tbl> as pq where pq.field_name = 'address_type'
		)) as missing_pct
from <Base Tbl> as pr
where ifnull(pr.partner_value,'') <>''
)

