(
  (<fao_calc.ti_grant>)
+ 
  sum(case 
/*imputed Pell/state funds are flagged in agg_syf table. Default is to include them in tgrant*/
	--when coalesce(agg_syf.imputed_flag,false) = true then 0

	  when agg_syf.eab_fund_type in ('federal_grant','state_grant','pell_grant')
	then agg_syf.agg_fund_amount

 else 0 end)
)

