/**Source of Truth = Query: Enroll360.Project Atlas Migration Checks.prioritized_test*/
/*this does not select rn=1 so we can use this table for investigative purposes*/
/*2026-06-04: switched pointing join to use normalized_exam_score instead of eab_exam_score - ccreekman*/
/*2026-04-30: aligned with <cte07_prioritized_test>*/

select * from (
	select distinct sts.*,
	coalesce(pdc.points,0) as points,
	coalesce(pdc.adj_points,0) as adj_points,
	row_number() over (partition by sts.partnercontact_id order by sts.intake_dt desc nulls last, coalesce(sts.normalized_exam_score,0) desc) as rn2

	from <cte06_normalized_test> sts

	left join <cte05_acrk_display> pdc
	on (pdc.configuration_type = 'exam_score_pointing'
	and coalesce(sts.normalized_exam_score,0) between coalesce(pdc.stored_value_exact_or_range_min,0) and coalesce(pdc.stored_value_range_max,99999999))

  	where coalesce(sts.normalized_exam_score,0) <> 0
	) agg

order by agg.partnercontact_id, agg.partner_system_name, rn2

/**Source of Truth = this variable <cte00_pop_definition>*/
/*edit to desired population(s), do not include more than one year for best results*/
(
/*entry year(s)*/
select 'eab_entry_year_academic' as field_name, '2026' as value

/*student type(s)*/
union all select 'eab_student_type' as field_name, 'Freshman' as value 
/*union all select 'eab_student_type' as field_name, 'Transfer' as value*/

/*entry term(s) - fall/summer are dashboard default*/
union all select 'eab_entry_term' as field_name, 'Fall' as value
union all select 'eab_entry_term' as field_name, 'Summer' as value

/*academic load*/
union all select 'eab_full_part_time' as field_name, 'Full-Time' as value
union all select 'eab_full_part_time' as field_name, 'Part-Time' as value
union all select 'eab_full_part_time' as field_name, 'Unknown' as value 

/*school state (residency) - state values are not standardized*/
union all select 'residency_state' as field_name, 'Ohio' as value 
union all select 'residency_state' as field_name, 'OH' as value 
/*union all select 'residency_state' as field_name, 'statevalue3' as value */

)

