/**Source of Truth = this variable <cte01_race>*/
(
select distinct
partnercontact_id, partner_system_name,
 case when coalesce(agg_race,'') like any ('%Black%','%Asian%','%Native%','%Middle%','%Multi%','%Other%') then 'POC' else 'non-POC' end as POC_rollup
from (
	select 
		partnercontact_id, partner_system_name,
		listagg(eab_race,'|') as agg_race 
  		from (
			select distinct
			stud_race.partnercontact_id, stud_race.partner_system_name, stud_race.eab_race
			from <tuple.StudentRace> stud_race
		) agg
	group by partnercontact_id, partner_system_name
) agg2
)

(
select  distinct COALESCE(((
   select ifnull(sum(pp.record_count),0) as unknown_total 
		from <Base Tbl> as pp where field_name = 'eab_admit_ind' and pp.eab_standard_value in ('Unmapped Value')
	   ) /
		(
		  select NULLIF(sum(pq.record_count),0) as total 
			from <Base Tbl> as pq where pq.field_name = 'eab_admit_ind'
		)),0) as missing_pct
from <Base Tbl> as pr
where ifnull(pr.partner_value,'') <>''
)

