select(
	select count(bt.primary_student_id) as denominator 
	from <Base Tbl> as bt)

left outer join (select pcm.client_value, pcm.standard_str_value from <[enrollment_services].[Partner Code Mapping]> pcm
  where pcm.field_name = <Admit Status Lookup Key> 
				 --‘adm_stat’ 
)  as adm_stat on (adm_stat.client_value=<Admit Indicator Pred>)
left outer join (select pcm.client_value, pcm.standard_str_value from <[enrollment_services].[Partner Code Mapping]> pcm
  where pcm.field_name = <Application Status Lookup Key> --‘app_stat’
)  as app_stat_completed on (app_stat_completed.client_value=<Application Completed Indicator Pred>)
left outer join (select pcm.client_value, pcm.standard_str_value from <[enrollment_services].[Partner Code Mapping]> pcm
  where pcm.field_name = <Application Decision Type Code Lookup Key> --‘decision_type’
)  as decision_type on (decision_type.client_value=<Application Decision Type Code Pred>)
left outer join (select pcm.client_value, pcm.standard_str_value from <[enrollment_services].[Partner Code Mapping]> pcm
  where pcm.field_name = <Application Status Lookup Key> --‘app_stat’
)  as app_stat_started on (app_stat_started.client_value=<Application Started Indicator Pred>)
left outer join (select pcm.client_value, pcm.standard_str_value from <[enrollment_services].[Partner Code Mapping]> pcm
  where pcm.field_name = <Application Type Lookup Key> -- ‘app_type’
)  as app_type on (app_type.client_value=<Application Type Pred>)
left outer join (select pcm.client_value, pcm.standard_str_value from <[enrollment_services].[Partner Code Mapping]> pcm
  where pcm.field_name = <Admit Status Lookup Key> -- ‘adm_stat’ 
)  as cond_adm_stat on (cond_adm_stat.client_value=<Conditional Admit Date Pred>)
left outer join (select pcm.client_value, pcm.standard_str_value from <[enrollment_services].[Partner Code Mapping]> pcm
  where pcm.field_name = <Deposit Status Lookup Key> -- ‘dep_stat’
)  as dep_stat on (dep_stat.client_value=<Deposit Confirmed Indicator Pred>)
left outer join (select pcm.client_value, pcm.standard_str_value from <[enrollment_services].[Partner Code Mapping]> pcm
  where pcm.field_name = <Enrollment Status Lookup Key> -- ‘enrl_stat’
)  as enrl_stat on (enrl_stat.client_value=<Enrollment Indicator Pred>)
left outer join (select pcm.client_value, pcm.standard_str_value from <[enrollment_services].[Partner Code Mapping]> pcm
  where pcm.field_name = <Waitlist Status Lookup Key> -- ‘waitlist_stat’
)  as waitlist_stat on (waitlist_stat.client_value=<Waitlisted Indicator Pred>)
left outer join (select pcm.client_value, pcm.standard_str_value from <[enrollment_services].[Partner Code Mapping]> pcm
  where pcm.field_name = <Withdrawal Status Lookup Key> -- ‘wd_stat’
)  as wd_stat on (wd_stat.client_value=<Withdrawn Indicator Pred>)

