 MIN(UPPER(regexp_replace(TRANSFER_COURSE_IND, ' ', '', 1, 0, 'i'))) over (partition by STUDENT_ID order by ROWNUMBER ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) as min_TRANSFER_COURSE_IND  
					  from ( select <Aggregator_AGG_transfer_course_ind.STUDENT_ID> as STUDENT_ID, <Aggregator_AGG_transfer_course_ind.rownumber> as rownumber,
