select sum(duplicate_key_combination) as duplicate_key_count
from (
	select count(*) as duplicate_key_combination 
	from (
		select src_donor_id, degree_desc, degree_major_desc, source_partner_system_name 
		from <[ams].[donor_degree].{final}> as a
		group by src_donor_id, degree_desc, degree_major_desc, source_partner_system_name
		having count(*) > 1
		) as A

	UNION ALL

	select count(*) as duplicate_key_combination 
	from (
		select src_donor_id, attribute_key, source_partner_system_name 
		from <[ams].[donor_attributes].{final}> as a
		group by src_donor_id, attribute_key, source_partner_system_name
		having count(*) > 1
		) as B

	) as Combined

select sum(duplicate_key_combination) as duplicate_key_count 
from (
	select count(*) as duplicate_key_combination 
	from (
		select src_donor_id, source_partner_system_name 
		from <[ams].[donor].{final}> as a
		group by src_donor_id, source_partner_system_name
		having count(*) > 1	
		) as A

UNION ALL

	select count(*) as duplicate_key_combination 
	from (
		select src_donor_id, email, source_partner_system_name 
		from <[ams].[donor_email].{final}> as a
	  	where email is not null
		group by src_donor_id, email, source_partner_system_name
		having count(*) > 1
		) as B

	) as Combined

